model.view:
{
  "version": 1,
  "state": [
    {
      "id": "down",
      "when": {
        "eq": [
          {
            "var": "up"
          },
          "FALSE"
        ]
      },
      "label": "On Air is down; the saved record remains"
    },
    {
      "id": "refusal",
      "when": {
        "eq": [
          {
            "var": "message"
          },
          "\"refused\""
        ]
      },
      "label": "Another Start is refused"
    },
    {
      "id": "gap",
      "when": {
        "eq": [
          {
            "var": "message"
          },
          "\"gap\""
        ]
      },
      "label": "Capture resumed in the same recording"
    },
    {
      "id": "automatic",
      "when": {
        "eq": [
          {
            "var": "message"
          },
          "\"automatic\""
        ]
      },
      "label": "On Air stopped the recording and gives its reason"
    },
    {
      "id": "all",
      "when": true,
      "label": "Recording session and saved finishing queue"
    }
  ],
  "step": [
    {
      "id": "crash",
      "when": {
        "all": [
          {
            "eq": [
              {
                "from": "up"
              },
              "TRUE"
            ]
          },
          {
            "eq": [
              {
                "to": "up"
              },
              "FALSE"
            ]
          }
        ]
      },
      "label": "On Air dies and capture ends"
    },
    {
      "id": "launch",
      "when": {
        "all": [
          {
            "eq": [
              {
                "from": "up"
              },
              "FALSE"
            ]
          },
          {
            "eq": [
              {
                "to": "up"
              },
              "TRUE"
            ]
          }
        ]
      },
      "label": "Launch with the saved record"
    },
    {
      "id": "all",
      "when": true,
      "label": "Handle a request, caller report, or session step"
    }
  ]
}

